        data[blockSizeU32] = 0xBBBBBBBB;
        data[blockSizeU32 + 1] = 0xAAAAAAAA;
        data[blockSizeU32 + 4] = 0xBBBBBBBB;
        data[blockSizeU32 + 5] = 0xAAAAAAAA;

